const table=`<table><thead><tr><th>Ауа райы</th><th>Температура</th><th>Серуен</th></tr></thead><tbody><tr><td>Күн ашық</td><td>Жылы</td><td class="yes">Иә</td></tr><tr><td>Жаңбыр</td><td>Суық</td><td class="no">Жоқ</td></tr><tr><td>Күн ашық</td><td>Суық</td><td class="yes">Иә</td></tr><tr><td>Жаңбыр</td><td>Жылы</td><td class="no">Жоқ</td></tr></tbody></table>`;
export const lessons=[[
 {title:'Шешім — сұрақтан басталады.',body:`<p>Далаға шығар алдында ауа райына қарайсың. Жаңбыр жауса — үйде қаласың. Күн ашық болса, келесі сұраққа өтесің. <b>Ағаш та осылай: бір шарт, екі бағыт.</b></p><div class="weather"><p id="weather-q">Жаңбыр жауып тұр ма?</p><button class="btn small" data-weather="1">Иә</button><button class="btn secondary small" data-weather="0">Жоқ</button><div class="weather-result" id="weather-result" aria-live="polite"></div></div><p class="source-note">Бұл ауа райы мысалының ережелері алдын ала берілген. Ал зертханадағы модель бөлулерді деректерден үйренеді.</p><div class="callout">Алғашқы түйін — root. Шарт — node. Бағыт — branch. Соңғы жауап — leaf.</div>`},
 {title:'Жақсы сұрақты деректер таңдайды.',body:`<p>Мына төрт мысалға қара. «Жылы ма?» деген сұрақ екі топта да аралас жауап қалдырады. Ал <b>«Жаңбыр бар ма?»</b> барлық жауапты дұрыс ажыратады.</p>${table}<p>Зертханада басқа, екі белгісі бар синтетикалық деректер қолданылған: x₁ және x₂. <b>«Ағашты өсіру»</b> батырмасы оның тереңдігін бір деңгейге арттырады.</p><div class="callout">Жақсы сұрақ — әртүрлі жауаптарды бір-бірінен жақсы ажырататын сұрақ.</div><p>Әр түйінде алгоритм ықтимал шектерді салыстырады. Жаңа екі топтың салмақталған Gini мәні ең аз болатын бөлуді таңдайды.</p>`},
 {title:'Аралас топтан — таза топқа.',body:`<p>Бір ыдыста екі түсті шар бар деп елестет. Түстер тең болса, келесі шардың түсін болжау қиын. Бір ғана түс қалса — жауап анық.</p><div class="mini-control"><label>Жасыл шарлар: <output id="g-a-out">5</output><input aria-label="Жасыл шар саны" id="g-a" type="range" min="0" max="10" value="5"></label><label>Сарғыш шарлар: <output id="g-b-out">5</output><input aria-label="Сарғыш шар саны" id="g-b" type="range" min="0" max="10" value="5"></label></div><div class="gini-balls" id="gini-balls"></div><div class="formula">Gini = 1 − Σpᵢ² = <span id="gini-value">0.500</span></div><p id="gini-explain">Әр түстің үлесі 0.5. Gini = 1 − 0.5² − 0.5² = 0.5.</p><p>Екі класта Gini 0 мен 0.5 аралығында. 0 — таза топ. Бұл өлшем бөлуді таңдауға көмектеседі; ол модельдің тест дәлдігі емес.</p>`},
 {title:'Тереңірек әрдайым жақсы ма?',body:`<p>Емтихан жауаптарын жаттап алған оқушы жаңа сұрақта қиналуы мүмкін. Терең ағаш та оқыту мысалдарын тым жақсы есте сақтайды. Бұл — <b>overfitting, артық үйрену.</b></p><p>Тереңдікті 1-ден 4-ке өзгерт. «Деректер» көрінісінде түсті аймақтар — ағаштың болжамы. Шеңберлер — оқыту, ромбтар — бөлек тест деректері. Белгіленген нүктені өзгертсең, ағаштың шешім жолы жаңарады.</p><div class="callout">Train дәлдігі мен test дәлдігін бірге қара. Жаңа деректердегі нәтиже маңызды.</div><p>Графикке басып жаңа оқыту нүктесін қос. Класын басқару тақтасынан таңда. Әр өзгерістен кейін модель қайта үйренеді.</p>`},
 {title:'Түсінікті модельдің күші.',body:`<div class="split-copy"><div><h3>Қай кезде пайдалы?</h3><p>Шешім жолын түсіндіру керек болса: өтінімдерді сұрыптау, қарапайым тәуекел ережелері, клиент санатын анықтау.</p></div><div><h3>Нені ескеру керек?</h3><p>Деректердегі аз өзгеріс ағашты қатты өзгертуі мүмкін. Өте терең ағаш күрделі әрі тұрақсыз болады.</p></div></div><p><b>Классификация</b> жапырақта класс береді. <b>Регрессия</b> санды болжайды: мысалы, үй бағасын. Регрессиялық ағаш жапырақтағы сандардың орташа мәнін қолдана алады.</p><p>Жалғыз ағаштың тұрақсыздығын азайту үшін бірнеше әртүрлі ағашты біріктірсек ше? Келесі тарау осы сұрақтан басталады.</p><p class="source-note">Негіз: берілген 9-лекция, Decision Tree туралы слайдтар. Зертхана — шағын CART іске асырылымы, Gini бойынша екілік бөлу.</p>`},
 {title:'Өзіңді тексер.',quiz:[['Ағаш алғашқы шартты қалай таңдайды?',['Кездейсоқ әдемі тармақ салады','Деректерді жақсы ажырататын бөлуді іздейді','Ең ұзын белгіні алады'],1,'Gini азаятын бөлулер салыстырылады. Алгоритм мақсатты жауаптарды пайдаланады.'],['Бір ғана класы бар топтың Gini мәні қандай?',['0','0.5','1'],0,'Топ таза: 1 − 1² = 0.'],['Оқыту дәлдігі 100% болса, не тексеру керек?',['Тест деректеріндегі нәтижені','Ағаштың түсін','Ештеңені'],0,'Модель оқыту мысалдарын жаттап алуы мүмкін. Бөлек тест жаңа деректерге жалпылауды тексереді.']]}
],[
 {title:'Бір шешімге — бірнеше көзқарас.',body:`<p>Бір маман қателесуі мүмкін. Бір-бірінен тәуелсіз ойлайтын мамандардың пікірін жинасақ, кейбір қателері бірін-бірі теңестіреді. Random Forest — осындай <b>әртүрлі ағаштар ансамблі.</b></p><p>Алдыңғы тараудағы ағаш енді жалғыз емес. Орман көрінісінде әр шағын ағашқа басып, оның дауысын тексер. Ағаш санын өзгертіп, ортақ жауапты бақыла.</p><div class="callout">Ағаштар бір-бірінің жауабын күтпейді. Әрқайсысы жеке үйренеді.</div><p>Ағаштардың қателері өзара байланысты болуы мүмкін. Сондықтан орманның пайдасы тек санында емес, әртүрлілігінде де.</p>`},
 {title:'Бір дерек — әртүрлі таңдама.',body:`<p>Қапшықтан бір нөмірді алып, қайта сал. Сосын тағы таңда. Бір нөмір бірнеше рет түсуі, басқасы мүлде түспеуі мүмкін. Бұл — <b>bootstrap, қайтарып іріктеу.</b></p><p>Төменде 20 объектіден алынған 20 таңдаудың нөмірлері көрсетіледі. Белгіленген жақтаулар — қайталанған объектілер.</p><div class="bootstrap" id="bootstrap"></div><button class="btn secondary small" id="resample">Қайта іріктеу ↻</button><p id="bootstrap-note" aria-live="polite"></p><p>Зертханада әр ағаш 40 оқыту нүктесінен bootstrap таңдамасын алады. Әр түйінде екі белгінің біреуі кездейсоқ таңдалып, сол белгінің ең жақсы шегі ізделеді.</p><div class="callout">Әр ағаш деректердің сәл басқа нұсқасымен үйренеді. Сондықтан олардың қателері де бірдей болмауы мүмкін.</div>`},
 {title:'Дауыстар бір шешімге айналады.',body:`<p>Жаңа нүктені орманның барлық ағашына жібереміз. Әрқайсысы жасыл не сарғыш класс ұсынады. Біздің зертханада <b>көпшілік дауысы</b> жеңеді; тең болса, жасыл класс таңдалады.</p><div class="formula">ŷ = majority(T₁(x), …, Tₙ(x))</div><p>Нүктенің x₁ және x₂ координаттарын өзгертіп көр. Дауыстардың бөлінуі мен соңғы класс бірден жаңарады. Бұл дауыс үлесі — калибрленген ықтималдық кепілі емес.</p><p>Регрессияда классқа дауыс берудің орнына ағаштардың сандық болжамдарының <b>орташа мәні</b> алынады.</p><div class="compare-line"><span class="mini-tree">⑂ ⑂ ⑂</span> → тәуелсіз болжамдар → ортақ жауап</div>`},
 {title:'Жалғыз ағаш пен орманды салыстыр.',body:`<p>Зертханада <b>«Бір ағаш»</b> пен <b>«Орман»</b> көріністерін ауыстыр. Деректер бірдей, ал боялған шешім аймақтары өзгереді. «Деректер» көрінісі жеке нүктелерді анық көрсетеді.</p><p>Класын таңдап, графикке жаңа нүктелер қос. Орманды қайта оқыт және тәуелсіз тест нүктелеріндегі дәлдікті салыстыр. Нәтиже әр таңдамада бірдей болмайды.</p><div class="callout">Көп ағаш мінсіз нәтиже бермейді. Ортақ қателікті тек дауыс санымен жою мүмкін емес.</div><p>Bagging бірнеше таңдамадағы модельдерді біріктіреді. Random Forest бұған әр бөлудегі кездейсоқ белгілер таңдауын қосады.</p>`},
 {title:'Тұрақтылықтың өз бағасы бар.',body:`<div class="split-copy"><div><h3>Күшті жақтары</h3><p>Кестелік деректердегі күрделі байланыстарды үйренеді. Жеке ағашқа қарағанда жиі тұрақтырақ. Ағаштарды қатар оқытуға болады.</p></div><div><h3>Шектеулері</h3><p>Көп ағаш көбірек жад пен есептеу қажет етеді. Бір болжамның бүкіл себебін түсіндіру жалғыз ағаштан қиынырақ.</p></div></div><p>Мысалдар: клиенттің кетуін болжау, жабдық ақауын анықтау, жер жамылғысын жіктеу. Нақты қолдануда сапаны бөлек деректермен тексеру керек.</p><p>Ал ағаштар бір уақытта дауыс бермей, кезекпен ортақ болжамды түзетсе ше? Бұл бізді Gradient Boosting-ке әкеледі.</p>`},
 {title:'Орманды түсіндің бе?',quiz:[['Bootstrap деген не?',['Қайтармай іріктеу','Қайтарып кездейсоқ іріктеу','Тек қате нүктелерді таңдау'],1,'Таңдалған объект қайтадан таңдалуы мүмкін. Кейбір объектілер таңдамаға кірмейді.'],['Random Forest ағаштары қалай үйренеді?',['Бір-бірінен тәуелсіз','Әрқайсысы алдыңғының қатесін түзетеді','Тек бір ағаш үйренеді'],0,'Ағаштар жеке таңдамалармен үйренеді. Алдыңғы болжамға тәуелді түзету — boosting идеясы.'],['100 ағаш неге кепілдік береді?',['100% дәлдікке','Қателердің жойылуына','Мінсіз дәлдікке кепілдік бермейді'],2,'Көбірек ағаш дауыс беруді тұрақтандыруы мүмкін, бірақ дерек пен белгілердің шектеулері қалады.']]}
],[
 {title:'Алғашқы болжамнан баста.',body:`<p>Мәтінді бірден мінсіз жазу қиын. Алдымен нобай, содан кейін нақты түзетулер жасайсың. Gradient Boosting те <b>қарапайым болжамнан</b> бастайды да, оны қадамдап жақсартады.</p><p>Графиктегі ақ нүктелер — оқыту мәндері. Алғашқы көлденең сызық — олардың орташа мәні. Сарғыш кесінділер болжамның әр нүктеден қаншалық алыс екенін көрсетеді.</p><div class="callout">Бір ағаш → тәуелсіз ағаштар → бірінен соң бірі қосылатын түзетулер. Енді біз ортақ модельді жетілдіреміз.</div><p>Бұл зертхана сандық мән болжайды: регрессия. Келесі ағашты қосып, болжам сызығының өзгерісін бақыла.</p>`},
 {title:'Қате келесі ағашқа жол көрсетеді.',body:`<p>Шын мән 5, ал болжам 3 болса, қалдық <b>5 − 3 = 2</b>. Жаңа ағаш осы қалдықтарды үйренеді. Оның жауабы ортақ модельге қосылады.</p><div class="formula">rᵢ = yᵢ − F(xᵢ)</div><p>«Келесі ағаш +» батырмасын бас. Әр қадамда тереңдігі 2 болатын жаңа регрессиялық ағаш оқытылады. Ескі ағаштар сақталады.</p><p id="boost-example">Бірінші түзетуді қосқанда, нақты сандық есеп осында шығады.</p><p>Қалдықтармен жұмыс істеу квадраттық қате үшін ыңғайлы. Жалпы жағдайда жаңа модель таңдалған loss функциясының <b>теріс градиентін</b> үйренеді. Қарапайым айтқанда, ол қатені азайтатын бағытты іздейді.</p>`},
 {title:'Әр түзетудің өз салмағы бар.',body:`<p>Бірден үлкен өзгеріс жасау міндетті емес. Learning rate, яғни <b>η — түзету үлесі</b>, жаңа ағаштың қанша бөлігі қосылатынын анықтайды.</p><div class="formula">Fₘ(x) = Fₘ₋₁(x) + η · hₘ(x)</div><div class="formula-keys"><b>Fₘ₋₁</b><span>Алдыңғы ортақ болжам</span><b>hₘ</b><span>Жаңа ағаш ұсынған түзету</span><b>η</b><span>Түзетудің үлесі: 0.01–1.00</span><b>Fₘ</b><span>Жаңартылған ортақ болжам</span></div><p>Слайдерді өзгерткенде сол қадам саны жаңа η мәнімен қайта оқытылады. Аз η көбіне көбірек ағаш қажет етеді; үлкен η жылдам өзгеріс береді. Ең жақсы мән деректерге байланысты.</p>`},
 {title:'Қате азайды. Қай деректе?',body:`<p>Орташа квадраттық қате — <b>MSE</b> — үлкен қателерге көбірек салмақ береді. Неғұрлым аз болса, болжам сол деректерге соғұрлым жақын.</p><div class="formula">MSE = (1/n) Σ(yᵢ − ŷᵢ)²</div><p>Төменгі графиктегі күлгін сызық — оқыту қатесі, сарғыш сызық — модель үйренбеген validation қатесі. Екі жиын да алдын ала бекітілген, жеке синтетикалық нүктелерден тұрады.</p><div class="callout">Train қатесі азая берсе де, validation қатесі өсуі мүмкін. Бұл артық үйренудің белгісі болуы ықтимал.</div><p>Қадамдарды арттыр, η мәнін өзгерт, екі қисықты салыстыр. Осы шағын мысалда validation қатесі міндетті түрде өспейді. Ерте тоқтату үшін бөлек validation жиыны қолданылады.</p>`},
 {title:'Екі ансамбль. Екі түрлі логика.',body:`<div class="split-copy"><div><h3>Random Forest</h3><p>Тәуелсіз мамандар. Әр ағаш бөлек үйренеді, соңында дауыстары не орташа болжамы біріктіріледі.</p><div class="compare-line"><span class="mini-tree">⑂ ⑂ ⑂</span> → Σ / n</div></div><div><h3>Gradient Boosting</h3><p>Кезектескен редакторлар. Әр жаңа ағаш сол сәттегі бүкіл модельдің қатесіне сүйеніп оқытылады.</p><div class="compare-line"><span class="mini-tree">⑂ → ⑂ → ⑂</span></div></div></div><p>Boosting кестелік деректерде: сұраныс, баға, тәуекел болжамдарында пайдалы. Оның параметрлерін мұқият таңдау қажет; ағаштарды бір-бірінен тәуелсіз оқыту мүмкін емес.</p><p><b>XGBoost, LightGBM, CatBoost</b> — осы отбасының кең қолданылатын іске асырылымдары. Бұл зертхана олардың орнын баспайды: мұнда MSE және шағын CART ағаштары арқылы негізгі идея көрсетілген.</p>`},
 {title:'Енді өзің түсіндір.',quiz:[['Жаңа ағаш нені түзетеді?',['Тек соңғы ағаштың жауабын','Бүкіл ағымдағы модельдің қатесін','Деректердегі шын жауаптарды'],1,'Жаңа ағаштың үлесі алдыңғы ортақ болжамға қосылады.'],['Алдыңғы болжам 3, түзету 2, η = 0.1. Жаңа болжам?',['5','3.2','2.1'],1,'3 + 0.1 × 2 = 3.2. Learning rate түзету үлесін азайтады.'],['Артық үйренуді қай көрсеткіш байқауға көмектеседі?',['Тек ағаш саны','Тек оқыту қатесі','Бөлек validation деректеріндегі қате'],2,'Жаңа деректердегі қате модельдің жалпылауын бағалауға көмектеседі.']]}
]];
